from typing import Literal
from pydantic import BaseModel, Field


class CommandPlan(BaseModel):
    """Structured command interpretation generated by the LLM."""

    command_name: str = Field(
        description=(
            "The Windows command name requested by the user, "
            "such as DIR, TASKLIST, or MKDIR."
        )
    )

    arguments: list[str] = Field(
        default_factory=list,
        description=(
            "Command arguments as separate strings. "
            "Never combine the command and arguments into a shell string."
        )
    )

    explanation: str = Field(
        description=(
            "A short explanation of what the requested command will do."
        )
    )

    status: Literal["ready", "unsupported", "clarification_required"] = Field(
        description=(
            "ready: A command has been identified. "
            "unsupported: The requested operation is not supported. "
            "clarification_required: More information is needed."
        )
    )
